export function eventWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={pending:null,running:false,nextDraft:null,context:null,openStep:0};
 const authored=()=>api.project().maps.flatMap(map=>map.markers.filter(n=>n.runtime).map(n=>({map,n})));
 function open(){const list=authored();api.modal('Events & triggers',`<p>Choose what starts an event, then put its actions in order. These actions are written into an edited GBA copy.</p><div class="event-recipes">${Object.entries(RECIPES).map(([id,r])=>`<button type="button" data-event-recipe="${id}"><b>${r.name}</b><small>${r.hint}</small></button>`).join('')}</div><div class="smart-actions"><button id="eventQuestTemplates" type="button">Quest templates</button><button id="eventQuestFlags" type="button">Named quest progress</button><button id="newGameEvent" type="button" class="primary">Place an event</button><button id="eventPortals" type="button">Portals</button><button id="eventGates" type="button">Gates</button><button id="eventMovement" type="button">Walking rules</button><button id="eventFields" type="button">HMs & ledges</button></div><label>Find an event<input id="eventSearch" type="search" placeholder="Name, dialogue or map"></label><div id="eventsList"></div><p class="hint-line">A events run when you face the tile and press A. Step events run each time you step onto their tile. Existing imported NPCs can use your new action sequence; other original game scripts are preserved.</p>`);const cards=()=>{$('#eventsList').innerHTML=list.filter(({map,n})=>(n.title+' '+map.name+' '+JSON.stringify(n.runtime)).toLowerCase().includes($('#eventSearch').value.toLowerCase())).map(({map,n})=>`<div class="world-row"><span><b>${esc(n.title)}</b><small>${esc(map.name)} · ${n.x},${n.y} · ${(n.runtime.trigger||'interact')==='step'?'Step on tile':'Face + A'} · ${sequenceOf(n).length} action${sequenceOf(n).length===1?'':'s'}${n.runtime.enabled===false?' · disabled':''}</small></span><button type="button" data-edit-event="${esc(n.id)}">Edit</button></div>`).join('')||'<p>No matching authored events yet.</p>';document.querySelectorAll('[data-edit-event]').forEach(b=>b.onclick=()=>{const item=list.find(a=>a.n.id===b.dataset.editEvent);api.loadMap(item.map.id);edit(item.n);});};cards();document.querySelectorAll('[data-event-recipe]').forEach(b=>b.onclick=()=>recipe(b.dataset.eventRecipe));$('#eventQuestTemplates').onclick=()=>api.scenes().open();$('#eventQuestFlags').onclick=manageFlags;$('#eventSearch').oninput=cards;$('#newGameEvent').onclick=()=>{state.nextHM=null;state.nextDraft=null;api.mode('event');api.close();api.toast('Tap the tile that will start this event.');};$('#eventPortals').onclick=()=>api.world().open('portals');$('#eventGates').onclick=()=>api.world().open('gates');$('#eventMovement').onclick=()=>api.world().open('movement');$('#eventFields').onclick=()=>api.field().open();}
 async function edit(old=null,x=0,y=0,draft=null,mapId=api.map().id){
  if(old?.creatureGift){api.creatures().editGift(old);return;}const n=draft||structuredClone(old||newEvent(x,y));if(!n.runtime)n.runtime={action:'sequence',trigger:'interact',steps:[{type:'say',text:'Hello there!'}]};n.runtime={action:'sequence',trigger:old?.runtime?.trigger||'interact',enabled:old?.runtime?.enabled!==false,blocksMovement:!!old?.runtime?.blocksMovement,steps:sequenceOf(n),...n.runtime};if(n.runtime.action==='dialogue'){n.runtime.steps=[{type:'say',text:n.runtime.text}];n.runtime.action='sequence';delete n.runtime.text;}
  const map=api.project().maps.find(m=>m.id===mapId),steps=n.runtime.steps;if(steps.some(s=>ADVANCED_EVENT_TYPES.has(s.type))||needsQuest(n)){if(!await ready())return;}state.openStep=Math.min(state.openStep,steps.length-1);
  api.modal(old?'Edit game event':'Create game event',`<label>Name<input id="eventName" maxlength="120" value="${esc(n.title)}"></label><div class="event-actor"><b>${n.npc?esc(n.npc.name):n.rom?.type==='npc'?'Imported NPC':'Tile / object interaction'}</b>${n.rom?.type==='npc'?'':'<button id="eventAppearance" type="button">'+(n.npc?'Change character':'Add a character')+'</button>'}</div><div class="field-row"><label>Start this event<select id="eventTrigger"><option value="interact" ${n.runtime.trigger==='interact'?'selected':''}>Face tile + press A</option><option value="step" ${n.runtime.trigger==='step'?'selected':''}>Step onto this tile</option></select></label><label class="check"><input id="eventEnabled" type="checkbox" ${n.runtime.enabled!==false?'checked':''}> Enabled</label></div><label class="check"><input id="eventSolid" type="checkbox" ${n.runtime.blocksMovement?'checked':''}> Solid tile (sign or object)</label><label class="check"><input id="eventOnce" type="checkbox" ${n.runtime.onceFlag||n.runtime.once?'checked':''}> Run once per saved game</label><label id="eventRepeatLabel">After completion, say<textarea id="eventRepeat" maxlength="4000">${esc(n.runtime.repeatText||'You have already completed this.')}</textarea></label><div class="event-step-list" id="eventSteps"></div><div class="smart-actions"><select id="eventAddType" aria-label="Action to add">${Object.entries(EVENT_ACTIONS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><button id="eventAdd" type="button">Add action</button></div><p class="hint-line">Actions run from top to bottom. Conditions and No answers stop the event safely. One-time events and named progress persist in the saved game. Movement follows your chosen directions.</p>${old?'<div class="smart-actions"><button id="eventDuplicate" type="button">Duplicate</button><button id="eventDelete" type="button" class="danger">Remove authored event</button></div>':''}`,async()=>{collect();if(n.runtime.once&&!await ready())throw Error('Persistent events need the verified source ROM.');if(n.npc){n.runtime.trigger='interact';n.runtime.blocksMovement=false;const r=movementAt(map,n.x,n.y,{ignoreFieldObjects:true});if(r.collision)throw Error('Place the character on walkable ground. Paint Walkable first.');if(map.markers.some(o=>o.id!==n.id&&o.npc&&o.x===n.x&&o.y===n.y))throw Error('Another character already occupies this tile.');}if(n.runtime.trigger==='step'&&n.runtime.enabled!==false){if(api.project().links.some(l=>l.runtime?.type==='portal'&&[l.from,...(l.twoWay?[l.to]:[])].some(e=>e.mapId===map.id&&e.x===n.x&&e.y===n.y)))throw Error('Place a step event beside the portal, so both can run.');if(map.markers.some(o=>o.id!==n.id&&o.x===n.x&&o.y===n.y&&o.runtime?.trigger==='step'&&o.runtime.enabled!==false))throw Error('This tile already has a step event. Edit that event to add more actions.');if(movementAt(map,n.x,n.y).objectBlocked||movementAt(map,n.x,n.y).fieldObject)throw Error('Move the blocking object before placing a step event here.');}api.change(()=>{if(n.runtime.once){const q=addQuestFlag(api.project(),'Once: '+n.title,n.runtime.onceFlag);n.runtime.onceFlag=q.id;}else delete n.runtime.onceFlag;delete n.runtime.once;validateEvent(n,api.project(),map);if(old)Object.assign(old,n);else map.markers.push(n);if(n.runtime.trigger==='step'){n.runtime.blocksMovement=false;setMovement(map,n.x,n.y,{mode:'walk'});}});api.refresh();api.toast('Event saved. Try it with Play check.');},'Save event');
  function collect(){n.title=$('#eventName').value.trim()||'Game event';n.runtime.trigger=$('#eventTrigger').value;n.runtime.enabled=$('#eventEnabled').checked;n.runtime.blocksMovement=!n.npc&&n.runtime.trigger==='interact'&&$('#eventSolid').checked;n.runtime.once=$('#eventOnce').checked;n.runtime.repeatText=$('#eventRepeat').value;n.text=steps.filter(s=>s.type==='say').map(s=>s.text).join('\n\n');document.querySelectorAll('[data-step-field]').forEach(input=>{const step=steps[+input.dataset.stepIndex],key=input.dataset.stepField;step[key]=input.type==='checkbox'?input.checked:input.type==='number'||input.dataset.number?+input.value:input.value;});document.querySelectorAll('[data-event-choice]').forEach(input=>{const i=+input.dataset.stepIndex,k=input.dataset.eventChoice;steps[i][k]=api.game().parseChoice(input.id,input.dataset.choiceKind);});document.querySelectorAll('[data-shop-choice]').forEach(input=>{steps[+input.dataset.stepIndex].items[+input.dataset.shopChoice]=api.game().parseChoice(input.id,'items');});n.text=steps.filter(s=>s.type==='say').map(s=>s.text).join('\n\n');}
  const hmFields=(s,i)=>`<label>Field effect<select data-step-field="effect" data-step-index="${i}">${[['flash','Use Flash'],['strength','Activate Strength'],['rocksmash','Break a Rock Smash rock'],['cut','Clear a Cut tree']].map(([id,label])=>`<option value="${id}" ${s.effect===id?'selected':''}>${label}</option>`).join('')}</select></label>${['cut','rocksmash'].includes(s.effect)?`<label>Target object<select data-step-field="targetId" data-step-index="${i}"><option value="">Choose a placed object</option>${(map.fieldObjects||[]).filter(o=>o.kind===s.effect).map(o=>`<option value="${esc(o.id)}" ${s.targetId===o.id?'selected':''}>${esc(o.name)} · ${o.x},${o.y}</option>`).join('')}</select></label>`:''}<label class="check"><input type="checkbox" data-step-field="requireHM" data-step-index="${i}" ${s.requireHM?'checked':''}> Require the matching HM and badge</label>`;
  if(n.npc&&$('#eventAppearance')){$('#eventAppearance').insertAdjacentHTML('afterend','<button id="eventClearAppearance" type="button">Use a tile interaction instead</button>');$('#eventClearAppearance').onclick=()=>{collect();delete n.npc;edit(old,0,0,n,mapId);};}
  const scalar=(s,i,key,label,type='number',extra='')=>`<label>${label}<input type="${type}" data-step-field="${key}" data-step-index="${i}" value="${esc(s[key]??'')}" ${extra}></label>`;
  const named=(s,i,key,label,kind)=>api.game().choice('event_'+i+'_'+key,label,kind,s[key]||0).replace('<input ',`<input data-event-choice="${key}" data-choice-kind="${kind}" data-step-index="${i}" `);
  const options=(s,i,key,label,list)=>`<label>${label}<select data-step-field="${key}" data-step-index="${i}">${list.map(([v,n])=>`<option value="${v}" ${String(s[key])===String(v)?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
  const questOptions=(s,i)=>options(s,i,'questId','Named progress',(api.project().questFlags||[]).map(q=>[q.id,q.name]));
  function advancedFields(s,i){if(s.type==='choice')return scalar(s,i,'text','Question','text','maxlength="4000"')+'<p class="hint-line">Yes continues. No/B ends this event.</p>';if(s.type==='condition')return options(s,i,'kind','Only continue when',[['item','Player has an item'],['money','Player has enough money'],['quest','Named quest progress'],['badge','Player has a badge']])+(s.kind==='item'?named(s,i,'itemId','Required item','items')+scalar(s,i,'quantity','Quantity','number','min="1" max="999"'):s.kind==='money'?scalar(s,i,'amount','Money needed','number','min="0" max="999999"'):s.kind==='quest'?questOptions(s,i)+`<label class="check"><input type="checkbox" data-step-field="value" data-step-index="${i}" ${s.value!==false?'checked':''}> Progress is complete (unchecked = not complete)</label>`:scalar(s,i,'badge','Badge number','number','min="1" max="8"'))+scalar(s,i,'failText','If unmet, say and end','text','maxlength="4000"');if(s.type==='item')return options(s,i,'operation','Action',[['give','Give item'],['take','Take item']])+named(s,i,'itemId','Item','items')+scalar(s,i,'quantity','Quantity','number','min="1" max="999"');if(s.type==='money')return options(s,i,'operation','Action',[['give','Give money'],['take','Take money']])+scalar(s,i,'amount','Amount','number','min="0" max="999999"');if(s.type==='heal')return'<p>Fully restores the party’s HP, PP and status using the native healing function.</p>';if(s.type==='shop')return`<p>Shop stock · choose named items. Prices come from Game workshop → Items.</p>${s.items.map((id,j)=>'<div class="shop-stock-row">'+api.game().choice('stock_'+i+'_'+j,'Item '+(j+1),'items',id).replace('<input ',`<input data-shop-choice="${j}" data-step-index="${i}" `)+`<button type="button" data-shop-remove="${i}:${j}" aria-label="Remove item">×</button></div>`).join('')}<button type="button" data-shop-add="${i}">Add stock item</button>`;if(s.type==='battle')return named(s,i,'trainerId','Trainer slot','trainers')+scalar(s,i,'intro','Before battle','text','maxlength="4000"')+scalar(s,i,'defeat','Trainer’s defeat line','text','maxlength="4000"')+'<p class="hint-line">Use Game workshop → Trainers to edit this team. Other native encounters using the same trainer share its defeated flag.</p>';if(s.type==='giveMon')return named(s,i,'species','Pokémon','species')+scalar(s,i,'level','Level','number','min="1" max="100"')+named(s,i,'itemId','Held item (optional)','items');if(s.type==='quest')return questOptions(s,i)+`<label class="check"><input type="checkbox" data-step-field="value" data-step-index="${i}" ${s.value?'checked':''}> Mark complete (unchecked = clear)</label><p>Create named progress in Events → Named quest progress first.</p>`;if(s.type==='sound')return options(s,i,'soundId','Sound',[[1,'Use item'],[5,'Select'],[8,'Door'],[39,'Warp in'],[40,'Warp out'],[241,'FireRed door']]).replace('data-step-field="soundId"','data-step-field="soundId" data-number="true"');if(s.type==='music'){const tracks=[...new Map(state.context.reader.maps.map(m=>[state.context.reader.u16(m.address+16),m.name])).entries()];return options(s,i,'songId','Use music from map',tracks).replace('data-step-field="songId"','data-step-field="songId" data-number="true"');}if(s.type==='fade')return options(s,i,'mode','Fade',[[0,'To black'],[1,'From black'],[2,'To white'],[3,'From white']]).replace('data-step-field="mode"','data-step-field="mode" data-number="true"');if(s.type==='portrait')return named(s,i,'species','Pokémon portrait','species');return'';}
  const fields=(s,i)=>s.type==='say'?`<label>Dialogue<textarea data-step-field="text" data-step-index="${i}" maxlength="4000">${esc(s.text)}</textarea></label>`:s.type==='wait'?`<label>Wait (frames, 60 = about one second)<input type="number" min="1" max="36000" data-step-field="frames" data-step-index="${i}" value="${s.frames}"></label>`:s.type==='move'?`<div class="field-row"><label>Who<select data-step-field="actor" data-step-index="${i}"><option value="player" ${s.actor==='player'?'selected':''}>Player</option>${n.rom?.type==='npc'||n.npc?`<option value="npc" ${s.actor==='npc'?'selected':''}>This character</option>`:''}</select></label><label>Direction<select data-step-field="direction" data-step-index="${i}">${['up','down','left','right'].map(d=>`<option ${d===s.direction?'selected':''}>${d}</option>`).join('')}</select></label><label>Tiles<input type="number" min="1" max="32" data-step-field="distance" data-step-index="${i}" value="${s.distance}"></label></div>`:s.type==='hm'?hmFields(s,i):ADVANCED_EVENT_TYPES.has(s.type)?advancedFields(s,i):s.type==='gate'?`<label>Gate<select data-step-field="gateId" data-step-index="${i}">${(map.gates||[]).map(g=>`<option value="${esc(g.id)}" ${s.gateId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>`:`<p>${s.to?esc(api.project().maps.find(m=>m.id===s.to.mapId)?.name)+' · '+s.to.x+','+s.to.y:'Choose an arrival tile.'}</p><button type="button" data-event-target="${i}">Pick destination on map</button>`;
  function render(){const holder=$('#eventSteps');holder.innerHTML=steps.map((s,i)=>`<details class="event-step" ${i===state.openStep?'open':''}><summary>${i+1}. ${esc(EVENT_ACTIONS[s.type])}</summary><div class="event-step-head"><strong>${i+1}. ${EVENT_ACTIONS[s.type]}</strong><div class="smart-actions"><button type="button" data-event-up="${i}" aria-label="Move action earlier" ${i===0?'disabled':''}>↑</button><button type="button" data-event-down="${i}" aria-label="Move action later" ${i===steps.length-1?'disabled':''}>↓</button><button type="button" data-event-remove="${i}" aria-label="Remove action">×</button></div></div>${fields(s,i)}</details>`).join('');document.querySelectorAll('[data-shop-add]').forEach(b=>b.onclick=()=>{collect();const stock=steps[+b.dataset.shopAdd].items;if(stock.length>=50){api.toast('Keep at most 50 stock items.');return;}stock.push(13);render();});document.querySelectorAll('[data-shop-remove]').forEach(b=>b.onclick=()=>{collect();const[i,j]=b.dataset.shopRemove.split(':').map(Number);steps[i].items.splice(j,1);render();});document.querySelectorAll('[data-step-field="kind"]').forEach(input=>input.onchange=()=>{collect();state.openStep=+input.dataset.stepIndex;render();});document.querySelectorAll('[data-step-field="effect"]').forEach(input=>input.onchange=()=>{collect();const step=steps[+input.dataset.stepIndex];step.targetId='';render();});document.querySelectorAll('[data-event-up],[data-event-down]').forEach(b=>b.onclick=()=>{collect();const i=+(b.dataset.eventUp??b.dataset.eventDown),j=i+(b.dataset.eventUp!==undefined?-1:1);[steps[i],steps[j]]=[steps[j],steps[i]];render();});document.querySelectorAll('[data-event-remove]').forEach(b=>b.onclick=()=>{collect();steps.splice(+b.dataset.eventRemove,1);render();});document.querySelectorAll('[data-event-target]').forEach(b=>b.onclick=()=>{collect();const i=+b.dataset.eventTarget;api.modal('Choose destination map',`<label>Map<select id="eventTargetMap">${api.project().maps.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></label><p>Next, tap the exact arrival tile.</p>`,()=>{state.pending={old,n,mapId,index:i};api.loadMap($('#eventTargetMap').value);api.mode('eventTarget');api.toast('Tap the event’s arrival tile.');},'Pick tile');});}
  if($('#eventAppearance'))$('#eventAppearance').onclick=()=>{collect();chooseNPCAppearance(api,{allowCustom:false,onBack:()=>edit(old,0,0,n,mapId),onOpenROM:()=>{state.appearanceDraft={oldId:old?.id,n,mapId};api.pickROM('eventAppearance');},onPick:({native})=>{const t=npcTemplates(api.session().reader).find(t=>t.graphics===native.graphics);n.npc={...native,facing:n.npc?.facing||'down',name:t.name};n.runtime.trigger='interact';n.runtime.blocksMovement=false;edit(old,0,0,n,mapId);}});};if(n.npc){$('#eventTrigger').value='interact';$('#eventTrigger').disabled=true;$('#eventSolid').checked=false;$('#eventSolid').disabled=true;}
  render();$('#eventOnce').onchange=()=>$('#eventRepeatLabel').hidden=!$('#eventOnce').checked;$('#eventOnce').onchange();$('#eventAdd').onclick=async()=>{collect();const type=$('#eventAddType').value;if(steps.length>=64){api.toast('Keep one event under 64 actions.');return;}if(ADVANCED_EVENT_TYPES.has(type)&&!await ready())return;steps.push(defaultStep(type,map));state.openStep=steps.length-1;render();};$('#eventTrigger').onchange=()=>{$('#eventSolid').disabled=$('#eventTrigger').value==='step';if($('#eventSolid').disabled)$('#eventSolid').checked=false;};$('#eventTrigger').onchange();
  if(old){$('#eventDelete').onclick=()=>{api.change(()=>map.markers=map.markers.filter(m=>m.id!==old.id));api.close();api.refresh();};$('#eventDuplicate').onclick=()=>{collect();const copy=structuredClone(n);copy.id=uid();copy.title+=' copy';delete copy.rom;api.change(()=>{if(copy.runtime.onceFlag){const q=addQuestFlag(api.project(),'Once: '+copy.title);copy.runtime.onceFlag=q.id;}map.markers.push(copy);});api.close();api.refresh();api.toast('Event copied. Move its pin to another tile.');};}
 }
 function tap(x,y){if(state.pending){const p=state.pending;p.n.runtime.steps[p.index].to={mapId:api.map().id,x,y};state.pending=null;api.loadMap(p.mapId);api.mode('move');edit(p.old,0,0,p.n,p.mapId);}else{const n=api.map().markers.find(n=>n.x===x&&n.y===y);if(state.nextDraft){const draft={...structuredClone(n||newEvent(x,y)),title:state.nextDraft.title,runtime:structuredClone(state.nextDraft.runtime)};draft.x=x;draft.y=y;state.nextDraft=null;edit(n||null,x,y,draft);}else if(state.nextHM){const draft=structuredClone(n||newEvent(x,y));draft.title='Use '+state.nextHM;draft.runtime={action:'sequence',trigger:'interact',enabled:true,blocksMovement:false,steps:[{type:'hm',effect:state.nextHM,requireHM:false}]};state.nextHM=null;edit(n||null,x,y,draft);}else edit(n||null,x,y);}}
 async function present(text,title){const pages=wrapDialogue(text).split('\\p').map(s=>s.replace(/\\n/g,'\n').replace(/\\\$/g,'$'));for(let i=0;i<pages.length;i++){const proceed=await new Promise(resolve=>{let submitted=false;api.modal(title,`<div class="dialogue-preview">${esc(pages[i]).replace(/\n/g,'<br>')}</div><p>${i+1} / ${pages.length}</p>`,()=>{submitted=true;resolve(true);},i+1<pages.length?'A · Next':'A · Continue');const dialog=$('#dialog');dialog.addEventListener('close',()=>{if(!submitted)resolve(false);},{once:true});});if(!proceed)return false;}return true;}
 async function run(n){if(state.running||n.runtime?.enabled===false)return;const play=api.world().state.play;if(!play)return;state.running=true;let completed=true;try{play.quests??=new Set();if(n.runtime.onceFlag&&play.quests.has(n.runtime.onceFlag)){await present(n.runtime.repeatText||'Already completed.',n.title);return;}for(const s of sequenceOf(n)){if(!api.world().state.play){completed=false;break;}if(s.type==='say'){if(!await present(s.text,n.title)){completed=false;break;}}else if(s.type==='wait'){for(let left=s.frames;left>0&&api.world().state.play===play;left-=30)await new Promise(r=>setTimeout(r,Math.min(30,left)/60*1000));}else if(s.type==='hm'){api.field().previewAction(s.effect,s.targetId,s.requireHM);}else if(s.type==='choice'){if(!await question(s.text,n.title)){completed=false;break;}}else if(s.type==='condition'){const ok=s.kind==='quest'?(play.quests?.has(s.questId)||false)===(s.value!==false):s.kind==='item'?(play.bag?.get(s.itemId)||0)>=s.quantity:s.kind==='money'?(play.money||0)>=s.amount:play.hmBadges?.has(s.badge);if(!ok){await present(s.failText||'Requirement not met.',n.title);completed=false;break;}}else if(s.type==='item'){play.bag??=new Map();const have=play.bag.get(s.itemId)||0;if(s.operation==='take'&&have<s.quantity){await present('You do not have the required item.',n.title);completed=false;break;}play.bag.set(s.itemId,have+(s.operation==='take'?-s.quantity:s.quantity));}else if(s.type==='money'){if(s.operation==='take'&&(play.money||0)<s.amount){await present('Not enough money.',n.title);completed=false;break;}play.money=Math.min(999999,(play.money||0)+(s.operation==='take'?-s.amount:s.amount));}else if(s.type==='quest'){play.quests??=new Set();s.value?play.quests.add(s.questId):play.quests.delete(s.questId);}else if(['heal','shop','battle','giveMon','sound','music','fade','portrait'].includes(s.type)){if(!await present('Quick check: '+EVENT_ACTIONS[s.type]+'. Use Play edited ROM for the actual game.',n.title)){completed=false;break;}}else if(s.type==='gate'){play.openGates.add(s.gateId);api.refresh();}else if(s.type==='warp'){api.loadMap(s.to.mapId,true);Object.assign(play,{mapId:s.to.mapId,x:s.to.x,y:s.to.y});clearFieldPreview(play,api.map());api.refresh();}else if(s.type==='move'){const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[s.direction];if(s.actor==='npc'){api.toast('NPC movement is compiled for the game; the editor shows NPC pins.');continue;}for(let i=0;i<s.distance;i++){const x=play.x+d[0],y=play.y+d[1];if(movementAt(api.map(),x,y,{openGates:play.openGates,fieldState:play}).collision)throw Error('This movement reaches a blocked tile. Adjust its route.');play.x=x;play.y=y;}api.refresh();}}if(completed&&n.runtime.onceFlag)play.quests.add(n.runtime.onceFlag);}catch(error){api.error(error);}finally{state.running=false;}}
 const RECIPES={dialogue:{name:'Talk / sign',hint:'Write a conversation',steps:[{type:'say',text:'Hello there!'}]},gift:{name:'Item gift',hint:'Ask, give, remember',once:true,steps:[{type:'choice',text:'Would you like a POTION?'},{type:'item',operation:'give',itemId:13,quantity:1},{type:'say',text:'You received a POTION!'}]},healer:{name:'Healer',hint:'Restore the whole party',steps:[{type:'say',text:'Let me heal your Pokémon.'},{type:'heal'},{type:'say',text:'Your Pokémon are ready!'}]},shop:{name:'Shopkeeper',hint:'Choose a named stock list',steps:[{type:'say',text:'Welcome! What do you need?'},{type:'shop',items:[13,4,14]}]},battle:{name:'Trainer battle',hint:'Choose a native trainer team',steps:[{type:'battle',trainerId:1,intro:'Let us battle!',defeat:'Well fought!'}]},pokemon:{name:'Pokémon gift',hint:'Species, level and held item',once:true,steps:[{type:'choice',text:'Will you look after this Pokémon?'},{type:'giveMon',species:25,level:5,itemId:0},{type:'say',text:'Take good care of your new friend!'}]},quest:{name:'Item exchange / quest',hint:'Requirement, reward, remember',once:true,steps:[{type:'condition',kind:'item',itemId:13,quantity:1,failText:'Bring me a POTION, please.'},{type:'item',operation:'give',itemId:4,quantity:1},{type:'item',operation:'take',itemId:13,quantity:1},{type:'say',text:'Thank you! Here is your reward.'}]},cutscene:{name:'Short cutscene',hint:'Sound, movement and dialogue',steps:[{type:'sound',soundId:5},{type:'wait',frames:30},{type:'say',text:'Did you hear that?'}]}};
 function defaultStep(type,map){return type==='say'?{type,text:'New dialogue'}:type==='wait'?{type,frames:60}:type==='move'?{type,actor:'player',direction:'up',distance:1}:type==='hm'?{type,effect:'flash',requireHM:false}:type==='gate'?{type,gateId:map.gates?.[0]?.id||''}:type==='warp'?{type,to:null}:type==='choice'?{type,text:'Continue?'}:type==='condition'?{type,kind:'item',itemId:13,quantity:1,amount:100,badge:1,questId:api.project().questFlags?.[0]?.id||'',value:true,failText:'You have not met this requirement.'}:type==='item'?{type,operation:'give',itemId:13,quantity:1}:type==='money'?{type,operation:'give',amount:100}:type==='shop'?{type,items:[13,4,14]}:type==='battle'?{type,trainerId:1,intro:'Let us battle!',defeat:'You won!'}:type==='giveMon'?{type,species:25,level:5,itemId:0}:type==='quest'?{type,questId:api.project().questFlags?.[0]?.id||'',value:true}:type==='sound'?{type,soundId:5}:type==='music'?{type,songId:state.context.reader.u16(state.context.reader.maps[0].address+16)}:type==='fade'?{type,mode:0}:type==='portrait'?{type,species:25}:{type};}
 async function ready(){try{state.context=await api.game().context();state.context={...state.context,profile:state.context.scriptProfile,data:state.context.data||{species:state.context.sprites?.names.map((name,id)=>({id,name}))||[],items:state.context.scene?.data.items||[],moves:[],trainers:[],abilities:[]}};return true;}catch(e){api.error(e);return false;}}
 async function recipe(id){const r=RECIPES[id];if(id!=='dialogue'&&!await ready())return;state.nextHM=null;state.nextDraft={title:r.name,runtime:{action:'sequence',trigger:'interact',enabled:true,blocksMovement:true,once:!!r.once,steps:structuredClone(r.steps)}};api.mode('event');api.close();api.toast('Tap an NPC, object or tile for '+r.name+'.');}
 function manageFlags(){api.modal('Named quest progress',`<p>Name story milestones, such as “Gate unlocked” or “Parcel delivered”. Native persistence is checked for the opened ROM during export.</p><div id="questFlagRows">${(api.project().questFlags||[]).map(q=>`<label>Name<input data-quest-name="${esc(q.id)}" value="${esc(q.name)}" maxlength="80"></label>`).join('')}</div><label>New milestone<input id="questNewName" maxlength="80" placeholder="Parcel delivered"></label><p class="hint-line">Milestone slots and their project owner stay stable. Keep this project when reopening a save.</p>`,()=>{api.change(()=>{document.querySelectorAll('[data-quest-name]').forEach(input=>{api.project().questFlags.find(q=>q.id===input.dataset.questName).name=input.value.trim()||'Quest progress';});if($('#questNewName').value.trim())addQuestFlag(api.project(),$('#questNewName').value.trim());});api.refresh();},'Save milestones');}
 async function question(text,title){return new Promise(resolve=>{let answered=false;api.modal(title,`<div class="dialogue-preview">${esc(text)}</div><button id="quickAnswerNo" type="button">No</button>`,()=>{answered=true;resolve(true);},'Yes');$('#quickAnswerNo').onclick=()=>{answered=true;api.close();resolve(false);};$('#dialog').addEventListener('close',()=>{if(!answered)resolve(false);},{once:true});});}
 return{state,open,edit,tap,run,async resumeAppearance(){const p=state.appearanceDraft;state.appearanceDraft=null;if(!p)return open();const old=api.project().maps.find(m=>m.id===p.mapId)?.markers.find(n=>n.id===p.oldId);await edit(old||null,0,0,p.n,p.mapId);$('#eventAppearance')?.click();},startHM:effect=>{state.nextHM=effect;api.mode('event');api.close();api.toast('Tap where the '+effect+' event should start.');}};
}
